com.mirth.connect.plugins.javascriptstep.script:
var tokenUrl = "http://localhost:8300/oauth2/default/token";

var params = "client_id=" + $('client_id') + 
		"&grant_type=password" +
		"&user_role=users" +
		"&scope=openid offline_access api:oemr api:fhir api:port user/allergy.read user/allergy.write user/appointment.read user/appointment.write user/dental_issue.read user/dental_issue.write user/document.read user/document.write user/drug.read user/encounter.read user/encounter.write user/facility.read user/facility.write user/immunization.read user/insurance.read user/insurance.write user/insurance_company.read user/insurance_company.write user/insurance_type.read user/list.read user/medical_problem.read user/medical_problem.write user/medication.read user/medication.write user/message.write user/patient.read user/patient.write user/practitioner.read user/practitioner.write user/prescription.read user/procedure.read user/soap_note.read user/soap_note.write user/surgery.read user/surgery.write user/transaction.read user/transaction.write user/vital.read user/vital.write user/AllergyIntolerance.read user/CareTeam.read user/Condition.read user/Coverage.read user/Encounter.read user/Immunization.read user/Location.read user/Medication.read user/MedicationRequest.read user/Observation.read user/Organization.read user/Organization.write user/Patient.read user/Patient.write user/Practitioner.read user/Practitioner.write user/PractitionerRole.read user/Procedure.read patient/encounter.read patient/patient.read patient/AllergyIntolerance.read patient/CareTeam.read patient/Condition.read patient/Coverage.read patient/Encounter.read patient/Immunization.read patient/MedicationRequest.read patient/Observation.read patient/Patient.read patient/Procedure.read" +
		"&username=admin" +
		"&password=pass";

var client = new Packages.org.apache.http.impl.client.HttpClientBuilder.create().build();
var httpPost = new Packages.org.apache.http.client.methods.HttpPost(tokenUrl);

httpPost.setHeader("Content-Type", "application/x-www-form-urlencoded");

var entity = new Packages.org.apache.http.entity.StringEntity(params, "UTF-8");
httpPost.setEntity(entity);

var response = client.execute(httpPost);

var responseEntity = response.getEntity();
var body = Packages.org.apache.http.util.EntityUtils.toString(responseEntity, "UTF-8");

var tokenJson = JSON.parse(body);
var accessToken = tokenJson['access_token'];

response.close();
channelMap.put("accessToken", accessToken);

// HttpClient erstellen
var client = Packages.org.apache.http.impl.client.HttpClientBuilder.create().build();
var baseUrl ="http://localhost:8300/apis/default/";

// Hilfsfunktion für Get-Request
function getJson(url) {
    var httpGet = new Packages.org.apache.http.client.methods.HttpGet(url);
    httpGet.setHeader("Authorization", "Bearer " + $('accessToken'));

    var response = client.execute(httpGet);
    var statusCode = response.getStatusLine().getStatusCode();

    if (statusCode != 200) {
        logger.error("Request failed: " + statusCode + " " + url + response.getStatusLine().getReasonPhrase());
        response.close();
        return {};
    }

    var body = Packages.org.apache.http.util.EntityUtils.toString(response.getEntity(), "UTF-8");
    response.close();
    return JSON.parse(body);
}

// Patient abrufen
var patientUrl = baseUrl + "fhir/Patient?" + $('param');

var patientBundle = getJson(patientUrl);
var patient = patientBundle.entry[0].resource;

// IPS Patient fixen
patient.meta = patient.meta || {};
patient.meta.profile = ["http://hl7.org/fhir/uv/ips/StructureDefinition/Patient-uv-ips"];

// unerlaubte Extensions entfernen
// patient.extension = [];
delete patient.extension;

// gender normalisieren
if (patient.gender === "unk") patient.gender = "unknown";

var uuid = patient.id;
channelMap.put('uuid', uuid);

// weitere Endpunkte
var endpoints = {
    conditions: baseUrl + "fhir/Condition?patient=" + uuid,
    medication: baseUrl + "fhir/MedicationRequest?patient=" + uuid,
    allergies: baseUrl + "fhir/AllergyIntolerance?patient=" + uuid,
    organisation: baseUrl + "fhir/Organization/a073088c-caff-440a-b8de-e4f2e2e61e00",
    immunization: baseUrl + "fhir/Immunization?patient=" + uuid,
    report: baseUrl + "fhir/DiagnosticReport?patient=" + uuid,
    observation: baseUrl + "fhir/Observation?patient=" + uuid,
    procedure: baseUrl + "fhir/Procedure?patient=" + uuid,
    device: baseUrl + "fhir/Device?patient=" + uuid
};

// Datenabfrage Hilfsfunktion
function loadSafe(resourceArray) {
    return (resourceArray.entry || []).map(function(e){ 
        var r = e.resource;
        // ICD & SNOMED Codes normalisieren
        if (r.code && r.code.coding) {
            r.code.coding.forEach(function(c){
                if (c.code) c.code = c.code.trim();
                if (c.display) c.display = c.display.replace(/\r?\n/g, '').trim();
            });
        }
        // MedicationRequest fix
        if (r.resourceType === "MedicationRequest" && (!r.intent || r.intent === "")) {
            r.intent = "order";
        }
        return e;
    });
}

// Daten abrufen
var conditions = loadSafe(getJson(endpoints.conditions));
var medication = loadSafe(getJson(endpoints.medication));
var allergies = loadSafe(getJson(endpoints.allergies));
var organisation = getJson(endpoints.organisation);
var immunization = loadSafe(getJson(endpoints.immunization));
var report = loadSafe(getJson(endpoints.report));
var observation = loadSafe(getJson(endpoints.observation));
var procedure = loadSafe(getJson(endpoints.procedure));
var device = loadSafe(getJson(endpoints.device));

// Composition-ID erzeugen
var compId = UUIDGenerator.getUUID();

// Sektionen Hilfsfunktion
function createSection(title, code, resources)
	{ const section = {
		title: title, 
		code: { coding: [{ system: "http://loinc.org", code: code }] }
		}; 
		if (resources && resources.length > 0) {
			section.entry = resources.map(e => ({ reference: "urn:uuid:" + e.resource.id })); 

			// Narrative übernehmen 
			const narratives = resources 
			.map(r => r.resource.text && r.resource.text.div ? r.resource.text.div : '') 
			.filter(d => d); // Narrative einfügen 
			section.text = { status: "generated", div: '<div xmlns="http://www.w3.org/1999/xhtml">' + title + '</div>' + 
			(narratives.length > 0 ? '<br/>' + narratives.join('<br/>') : '') }; 
			// Sicherstellen, dass jede Resource ein text-Element hat 
			resources.forEach(r => { if (!r.resource.text || !r.resource.text.div) { 
				r.resource.text = { status: "generated", 
				div: '<div xmlns="http://www.w3.org/1999/xhtml">' + title + '</div>' 
				};
			}});
    } else {
    	section.emptyReason = {
    		coding: [{
    			system: "http://terminology.hl7.org/CodeSystem/list-empty-reason",
    			code: "nilknown",
    			display: "Nil Known"}]
    		};
        // Keine Ressourcen vorhanden
        section.text = {
            status: "generated",
            div: '<div xmlns="http://www.w3.org/1999/xhtml">' + title + ': No information available</div>'
        };
    }
    return section;
}

// Composition erzeugen
var composition = {
    resourceType: "Composition",
    id: compId,
    status: "final",
    text: {
        status: "generated",
        div: '<div xmlns="http://www.w3.org/1999/xhtml">' +
             'International Patient Summary<br/>' +
             'Dies ist ein automatisch generiertes Dokument fuer Patient ' + patient.name[0].given.join(' ') + ' ' + patient.name[0].family +
             '</div>'
    },
    type: {
        coding: [{
            system: "http://loinc.org",
            code: "60591-5",
            display: "Patient summary document"
        }]
    },
    subject: { reference: "urn:uuid:" + patient.id },
    author: [{ reference: "urn:uuid:" + organisation.id }],
    date: new Date().toISOString(),
    title: "International Patient Summary",
    section: [
    createSection("Problems", "11450-4", conditions),
    createSection("Medications", "10160-0", medication),
    createSection("Allergies", "48765-2", allergies),
    createSection("Immunizations", "11369-6", immunization),
    createSection("Observations", "57016-8", observation),
    createSection("Procedures", "47519-4", procedure),
    createSection("Devices", "46264-8", device),
    createSection("Diagnostic Reports", "30954-2", report)
    ]
};

// Bundle erzeugen
var bundle = {
    resourceType: "Bundle",
    type: "document",
    identifier: { system: "urn:ietf:rfc:3986", value: "urn:uuid:" + compId },
    timestamp: new Date().toISOString(),
    entry: []
};

// Composition
bundle.entry.push({
    fullUrl: "urn:uuid:" + compId,
    resource: composition
});

// Patient
bundle.entry.push({
    fullUrl: "urn:uuid:" + patient.id,
    resource: patient
});

// Autor
bundle.entry.push({
    fullUrl: "urn:uuid:" + organisation.id, 
    resource: organisation
});

// Push Entries Hilfsfunktion
function addEntries(arr) {
    arr.forEach(function(e) {
        bundle.entry.push({
            fullUrl: "urn:uuid:" + e.resource.id,
            resource: e.resource
        });
    });
}

// Einträge hinzufügen
addEntries(conditions);
addEntries(medication);
addEntries(allergies);
addEntries(immunization);
addEntries(observation);
addEntries(procedure);
addEntries(device);
addEntries(report);

json = JSON.stringify(bundle, null, 2);
// Falsche Felder ersetzen
json = json
    // ICD-10 Legacy OID ersetzen
    .replace(/"system"\s*:\s*"2\.16\.840\.1\.113883\.6\.90"/g, '"system":"http://hl7.org/fhir/sid/icd-10-cm"')
    // References auf UUID-Format bringen
    .replace(/"reference"\s*:\s*"([A-Za-z]+)\/([A-Za-z0-9\-.]+)"/g, '"reference": "urn:uuid:$2"')
    // ICD-10 Prefix "ICD10:" entfernen
    .replace(/"system"\s*:\s*"http:\/\/hl7\.org\/fhir\/sid\/icd-10-cm"\s*,\s*"code"\s*:\s*"ICD10:([A-Z0-9\.]+)"/g,
             '"system":"http://hl7.org/fhir/sid/icd-10-cm","code":"$1"')
    // data-absent-reason#unknown auf gültigen clinicalStatus-Code setzen
    .replace(/"system"\s*:\s*"http:\/\/terminology\.hl7\.org\/CodeSystem\/data-absent-reason"/g, '"system":"http://terminology.hl7.org/CodeSystem/condition-clinical"')
    // Negative Jahreszahlen entfernen 
    .replace(/"-0001-11-30T00:00:00\+01:00"/g, '"1970-01-01T00:00:00Z"');
msg = json;

channel.postprocessingScript:
// This script executes once after a message has been processed
// Responses returned from here will be stored as "Postprocessor" in the response map
return;

channel.deployScript:
// This script executes once when the channel is deployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;

channel.undeployScript:
// This script executes once when the channel is undeployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;
